 "content": "def transform(grid):
    """Extend the central row and column of each solid 3x3 color block."""
    h, w = len(grid), len(grid[0])
    lines = {}
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                center = (r + 1, c + 1)
                lines.setdefault(center, set()).add(color)
    out = [row[:] for row in grid]
    claims = {}
    for (r, c), colors in lines.items():
        for j in range(w):
            claims.setdefault((r, j), set()).update(colors)
        for i in range(h):
            claims.setdefault((i, c), set()).update(colors)
    for (r, c), colors in claims.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out

